package dev.networkwatch;import java.util.*;
public final class Timeline {public record Bucket(long start,long end,long failedAuth,long bytes){}public List<Bucket> bucket(List<Analyzer.Event> events,long width){if(width<=0)throw new IllegalArgumentException("width must be positive");var grouped=new TreeMap<Long,List<Analyzer.Event>>();events.forEach(e->grouped.computeIfAbsent(e.epoch()/width*width,k->new ArrayList<>()).add(e));return grouped.entrySet().stream().map(x->new Bucket(x.getKey(),x.getKey()+width,x.getValue().stream().filter(e->e.kind().equals("auth")&&!e.success()).count(),x.getValue().stream().mapToLong(Analyzer.Event::bytes).sum())).toList();}}
